public class CarTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Car car = new Car(10.0);
        check("new car is not running", false, car.isRunning());
        check("new car has its fuel", 10.0, car.getFuel());

        car.drive(4);
        check("driving before start burns nothing", 10.0, car.getFuel());

        car.start();
        check("car runs after start", true, car.isRunning());

        car.drive(4);
        check("drive(4) burns 2.0 fuel", 8.0, car.getFuel());

        car.drive(6);
        check("drive(6) burns 3.0 more", 5.0, car.getFuel());

        car.drive(20);
        check("running dry leaves fuel at 0.0", 0.0, car.getFuel());
        check("engine shut off when fuel ran out", false, car.isRunning());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

