class Engine {

    private boolean running = false;
    private double fuelLevel;

    Engine(double fuelLevel) {
        this.fuelLevel = fuelLevel;
    }

    void start() {
        if (fuelLevel > 0) {
            running = true;
        }
    }

    boolean isRunning() {
        return running;
    }

    double getFuelLevel() {
        return fuelLevel;
    }

    void consumeFuel(double amount) {
        fuelLevel = fuelLevel - amount;
        if (fuelLevel <= 0) {
            fuelLevel = 0;
            running = false;
        }
    }
}

public class Car {

    private Engine engine;

    public Car(double fuel) {
        this.engine = new Engine(fuel);
    }

    public void start() {
        engine.start();
    }

    public boolean isRunning() {
        return engine.isRunning();
    }

    public double getFuel() {
        return engine.getFuelLevel();
    }

    public void drive(int km) {
        if (engine.isRunning()) {
            engine.consumeFuel(km * 0.5);
        }
    }
}
